//! Generates roastedduck's (de)serialization code from DuckDB's own specs.
//!
//! DuckDB generates its serializers from `src/include/duckdb/storage/serialization/*.json`
//! (`scripts/generate_serialization.py`) and its enum string tables from the C++ headers
//! (`scripts/generate_enum_util.py`). This tool does the same for Rust, from a snapshot of
//! those inputs in `tools/codegen/specs/`:
//!
//! ```text
//! cargo run -p codegen                       # regenerate every `src/generated/` file
//! cargo run -p codegen -- --check            # fail if a generated file is stale
//! cargo run -p codegen -- import <duckdb>    # refresh specs/ from a DuckDB source tree
//! ```

mod config;
mod cpp_enums;
mod cpp_type;
mod emit;
mod model;
mod names;
mod spec;

use std::collections::{BTreeMap, BTreeSet};
use std::io::Write as _;
use std::path::{Path, PathBuf};
use std::process::{Command, ExitCode, Stdio};

use config::{Content, TARGETS};
use cpp_enums::EnumDef;
use emit::{Emitter, emit_mod_file};
use model::{Home, Model};

type Result<T, E = Box<dyn std::error::Error>> = std::result::Result<T, E>;

fn workspace_root() -> PathBuf {
    let manifest = Path::new(env!("CARGO_MANIFEST_DIR"));
    manifest
        .parent()
        .and_then(Path::parent)
        .map_or_else(|| manifest.to_path_buf(), Path::to_path_buf)
}

fn specs_dir() -> PathBuf {
    workspace_root().join("tools/codegen/specs")
}

/// Formats generated source with the workspace's rustfmt settings.
fn rustfmt(source: &str) -> Result<String> {
    let root = workspace_root();
    let mut child = Command::new("rustfmt")
        .args(["--edition", "2024", "--emit", "stdout", "--config-path"])
        .arg(root.join("rustfmt.toml"))
        .current_dir(&root)
        .stdin(Stdio::piped())
        .stdout(Stdio::piped())
        .stderr(Stdio::piped())
        .spawn()?;
    child
        .stdin
        .take()
        .ok_or("rustfmt stdin unavailable")?
        .write_all(source.as_bytes())?;
    let output = child.wait_with_output()?;
    if !output.status.success() {
        return Err(format!(
            "rustfmt failed:\n{}\n--- source ---\n{source}",
            String::from_utf8_lossy(&output.stderr)
        )
        .into());
    }
    Ok(String::from_utf8(output.stdout)?)
}

fn version_map_source(model: &Model) -> String {
    let entries: Vec<String> = model
        .versions
        .serialization
        .iter()
        .map(|(name, version)| format!("({name:?}, {version})"))
        .collect();
    format!(
        "//! Generated by `tools/codegen` from DuckDB's `version_map.json`; do not edit.\n\n\
         /// DuckDB release names and the serialization format version each one writes.\n\
         pub(crate) const SERIALIZATION_VERSIONS: &[(&str, u64)] = &[{}];\n",
        entries.join(", ")
    )
}

/// Every generated file with its expected contents.
fn generate() -> Result<Vec<(PathBuf, String)>> {
    let specs = specs_dir();
    let enums: BTreeMap<String, EnumDef> =
        serde_json::from_str(&std::fs::read_to_string(specs.join("enums.json"))?)?;
    let model = Model::load(&specs, enums)?;
    let root = workspace_root();
    let mut files = Vec::new();
    for target in TARGETS {
        let dir = root.join(target.crate_dir).join("src/generated");
        files.push((dir.join("mod.rs"), rustfmt(&emit_mod_file(target.modules))?));
        for module in target.modules {
            let home = Home {
                crate_name: target.crate_name,
                module: module.name,
            };
            let source = match &module.content {
                Content::VersionMap => version_map_source(&model),
                Content::Enums(names) => {
                    let mut emitter = Emitter::new(&model, home, target.derives);
                    for name in *names {
                        emitter.emit_enum(name, &model.enums[*name])?;
                    }
                    emitter.finish("enum definitions (C++ headers and `enum_util.cpp`)")
                }
                Content::Classes { spec, .. } | Content::Properties { spec, .. } => {
                    let mut emitter = Emitter::new(&model, home.clone(), target.derives);
                    let mut classes: Vec<_> = model.classes.values().filter(|c| c.home == home).collect();
                    classes.sort_by_key(|c| c.order);
                    for class in classes {
                        let emitted = if class.properties {
                            emitter.emit_properties(class)
                        } else {
                            emitter.emit_class(class)
                        };
                        emitted.map_err(|e| format!("{}: {e}", class.spec.class))?;
                    }
                    emitter.finish(&format!("`{spec}`"))
                }
            };
            files.push((dir.join(format!("{}.rs", module.name)), rustfmt(&source)?));
        }
    }
    Ok(files)
}

/// Refreshes `specs/` from a DuckDB source tree.
fn import(duckdb: &Path) -> Result<()> {
    let specs = specs_dir();
    std::fs::create_dir_all(&specs)?;
    let source_dir = duckdb.join("src/include/duckdb/storage/serialization");
    let mut wanted = BTreeSet::new();
    let mut names: Vec<_> = std::fs::read_dir(&source_dir)?
        .filter_map(std::result::Result::ok)
        .map(|e| e.path())
        .filter(|p| p.extension().is_some_and(|e| e == "json"))
        .collect();
    names.sort();
    for path in names {
        let file_name = path.file_name().ok_or("bad spec path")?;
        std::fs::copy(&path, specs.join(file_name))?;
        for class in spec::read_spec_file(&path)? {
            for member in &class.members {
                if let Ok(ty) = cpp_type::CppType::parse(&member.cpp_type) {
                    let mut named = Vec::new();
                    ty.named_types(&mut named);
                    wanted.extend(named);
                }
            }
        }
    }
    std::fs::copy(
        duckdb.join("src/storage/version_map.json"),
        specs.join("version_map.json"),
    )?;
    for target in TARGETS {
        for module in target.modules {
            if let Content::Enums(names) = module.content {
                wanted.extend(names.iter().map(|n| (*n).to_owned()));
            }
        }
    }
    let enums = cpp_enums::import(duckdb, &wanted)?;
    let json = serde_json::to_string_pretty(&enums)? + "\n";
    std::fs::write(specs.join("enums.json"), json)?;
    println!(
        "imported {} enums and the serialization specs into {}",
        enums.len(),
        specs.display()
    );
    Ok(())
}

fn run() -> Result<bool> {
    let args: Vec<String> = std::env::args().skip(1).collect();
    match args.iter().map(String::as_str).collect::<Vec<_>>().as_slice() {
        ["import", duckdb] => {
            import(Path::new(duckdb))?;
            Ok(true)
        }
        [] => {
            for (path, contents) in generate()? {
                if let Some(dir) = path.parent() {
                    std::fs::create_dir_all(dir)?;
                }
                if std::fs::read_to_string(&path).ok().as_deref() != Some(contents.as_str()) {
                    std::fs::write(&path, contents)?;
                    println!("wrote {}", path.display());
                }
            }
            Ok(true)
        }
        ["--check"] => {
            let mut fresh = true;
            for (path, contents) in generate()? {
                if std::fs::read_to_string(&path).ok().as_deref() != Some(contents.as_str()) {
                    eprintln!("stale: {}", path.display());
                    fresh = false;
                }
            }
            if fresh {
                println!("generated code is up to date");
            } else {
                eprintln!("run `cargo run -p codegen` to regenerate");
            }
            Ok(fresh)
        }
        _ => Err("usage: codegen [--check | import <duckdb-source-dir>]".into()),
    }
}

fn main() -> ExitCode {
    match run() {
        Ok(true) => ExitCode::SUCCESS,
        Ok(false) => ExitCode::FAILURE,
        Err(error) => {
            eprintln!("codegen: {error}");
            ExitCode::FAILURE
        }
    }
}

#[cfg(test)]
mod tests {
    /// The checked-in generated files are what the specs and configuration produce (the
    /// check of `cargo run -p codegen -- --check`).
    #[test]
    fn generated_code_is_up_to_date() {
        for (path, contents) in super::generate().unwrap() {
            let on_disk = std::fs::read_to_string(&path).unwrap_or_default();
            assert!(
                on_disk == contents,
                "{} is stale; run `cargo run -p codegen`",
                path.display()
            );
        }
    }
}
